`),dU=[Hi,"","struct VertexInput {","    @location(0) position: vec3f,","    @location(1) normal: vec3f,","    @location(2) uv: vec2f,","    @location(3) tangent: vec4f,","    @location(4) instanceMatrix0: vec4f,","    @location(5) instanceMatrix1: vec4f,","    @location(6) instanceMatrix2: vec4f,","    @location(7) instanceMatrix3: vec4f,","    @location(8) instanceColor: vec4f,","};","","struct VertexOutput {","    @builtin(position) clipPos: vec4f,","    @location(0) worldPos: vec3f,","    @location(1) normal: vec3f,","    @location(2) uv: vec2f,","    @location(3) tangent: vec3f,","    @location(4) bitangent: vec3f,","    @location(5) instanceColor: vec4f,","};","","@group(0) @binding(0) var<uniform> frame: FrameUniforms;","","@vertex fn vertexMain(in: VertexInput) -> VertexOutput {","    var out: VertexOutput;","    let model = mat4x4f(in.instanceMatrix0, in.instanceMatrix1, in.instanceMatrix2, in.instanceMatrix3);","    let world = model * vec4f(in.position, 1.0);","    out.worldPos = world.xyz;","    out.normal = normalize((model * vec4f(in.normal, 0.0)).xyz);","    out.uv = in.uv;","    let T = normalize((model * vec4f(in.tangent.xyz, 0.0)).xyz);","    let N = out.normal;","    out.tangent = T;","    out.bitangent = cross(N, T) * in.tangent.w;","    out.instanceColor = in.instanceColor;","    out.clipPos = frame.projMatrix * frame.viewMatrix * world;","    return out;","}"].join(`
